import json
import re
import sys

status="invalid"; failureCode="400"; failureMessage="Input validation failed"; failureError="One or more rename inputs are invalid."; failureResult="{}"
organizationName=sys.argv[1].strip(); deploymentName=sys.argv[2].strip(); newDeploymentName=sys.argv[3].strip(); confirmRename=sys.argv[4].strip().lower()=="true"; waitRequested=sys.argv[5].strip().lower()=="true"
try: waitTimeout=int(sys.argv[6].strip())
except Exception: waitTimeout=0
errors=[]; namePattern=re.compile(r"^[a-zA-Z0-9][a-zA-Z0-9\- _]{0,31}$")
if not organizationName: errors.append("Workload Organization must not be blank.")
if not namePattern.fullmatch(deploymentName): errors.append("Current Workload Deployment Name is invalid.")
if not namePattern.fullmatch(newDeploymentName): errors.append("New Workload Deployment Name is invalid.")
if deploymentName==newDeploymentName: errors.append("New Workload Deployment Name must differ from the current name.")
if not confirmRename: errors.append("Confirm Rename must be true.")
if waitRequested and not (1<=waitTimeout<=600): errors.append("Wait Timeout Seconds must be 1 through 600 when waiting.")
if not waitRequested and not (0<=waitTimeout<=600): errors.append("Wait Timeout Seconds must be 0 through 600 when not waiting.")
escapedOrganizationName=organizationName.replace("'","''"); escapedDeploymentName=deploymentName.replace("'","''"); escapedNewDeploymentName=newDeploymentName.replace("'","''"); waitRequestedText="true" if waitRequested else "false"
if errors: failureError=" ".join(errors); failureResult=json.dumps({"error":failureMessage,"details":failureError},separators=(",",":"))
else: status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"

import json
import sys
status="invalid"; failureCode="500"; failureMessage="Rename request mapping failed"; failureError="The rename body could not be built."; failureResult="{}"; requestBody=""
try:
    newName=sys.argv[1]
    payload={"ClassId":"workload.WorkloadDeployment","ObjectType":"workload.WorkloadDeployment","RenameRequest":{"ClassId":"workload.RenameRequest","ObjectType":"workload.RenameRequest","Action":"Rename","NewName":newName}}
    requestBody=json.dumps(payload,separators=(",",":"),ensure_ascii=False,allow_nan=False); status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"
except Exception as exc:
    failureError="Rename mapping failed closed before PATCH: "+str(exc); failureResult=json.dumps({"error":failureMessage,"details":failureError,"mutationSent":False},separators=(",",":"))

import json
import sys
import time

status="invalid"; failureCode="500"; failureMessage="Polling delay failed"; failureError="The bounded polling delay could not complete."; failureResult="{}"
try:
    deadline=float(sys.argv[1]); initial=float(sys.argv[2]); interval=float(sys.argv[3]); attempt=int(sys.argv[4])
    if attempt<1 or attempt>5: raise ValueError("Poll attempt must be 1 through 5.")
    requested=initial if attempt==1 else interval; remaining=deadline-time.time()
    if remaining<=0:
        failureCode="408"; failureMessage="Lifecycle wait timed out"; failureError="The deadline was reached before poll attempt "+str(attempt)+"."; failureResult=json.dumps({"error":failureMessage,"requestAccepted":True,"timeout":True,"pollAttempt":attempt},separators=(",",":"))
    else:
        time.sleep(min(requested,remaining)); status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"
except Exception as exc:
    failureError="Polling delay helper failed: "+str(exc); failureResult=json.dumps({"error":failureMessage,"details":failureError,"requestAccepted":True},separators=(",",":"))

import datetime
import json
import sys
status="invalid"; failureCode="502"; failureMessage="Rename poll response was invalid"; failureError="The rename status response could not be validated."; failureResult="{}"; pollState="invalid"; pollResult="{}"
try:
    item=json.loads(sys.argv[1]); expectedMoid=sys.argv[2]; oldName=sys.argv[3]; newName=sys.argv[4]; orgMoid=sys.argv[5]; preModTime=sys.argv[6]
    if item.get("Moid")!=expectedMoid or item.get("ClassId")!="workload.WorkloadDeployment" or item.get("ObjectType")!="workload.WorkloadDeployment": raise ValueError("Deployment identity does not match.")
    org=item.get("Organization")
    if not isinstance(org,dict) or org.get("Moid")!=orgMoid: raise ValueError("Organization relationship does not match.")
    observedName=str(item.get("Name","")).strip(); modTime=str(item.get("ModTime","")).strip(); datetime.datetime.fromisoformat(modTime.replace("Z","+00:00"))
    rename=item.get("RenameRequest")
    if not isinstance(rename,dict) or rename.get("ClassId")!="workload.RenameRequest" or rename.get("ObjectType")!="workload.RenameRequest": raise ValueError("RenameRequest is missing or has inconsistent discriminators.")
    renameStatus=str(rename.get("Status","")).strip()
    if renameStatus not in {"None","Updating","UpdateScheduled"}: raise ValueError("RenameRequest.Status is outside the documented enum.")
    if observedName not in {oldName,newName}: raise ValueError("Observed Name is neither the old nor requested new name.")
    if observedName==newName and renameStatus=="None" and (modTime!=preModTime or oldName!=newName): pollState="success"
    else: pollState="progress"
    pollResult=json.dumps({"Moid":expectedMoid,"OldName":oldName,"NewName":newName,"ObservedName":observedName,"RenameStatus":renameStatus,"ModTime":modTime,"acknowledged":renameStatus in {"Updating","UpdateScheduled"} or observedName==newName or modTime!=preModTime,"preMutationModTime":preModTime,"raceDisclosure":"The deployment state was read before PATCH, but the request carried no version precondition; a concurrent same-item change can race the write."},separators=(",",":"))
    status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"
except Exception as exc:
    failureError="Rename poll validation failed: "+str(exc); failureResult=json.dumps({"error":failureMessage,"details":failureError,"requestAccepted":True,"preMutationModTime":preModTime,"raceDisclosure":"The lookup and PATCH were separate and may have raced a concurrent same-item change."},separators=(",",":"))
